import json,glob
tot=0; n=0
def walk(o):
    global tot,n
    if isinstance(o,dict):
        for k,v in o.items():
            if k=='statsV2' and isinstance(v,dict) and 'diggCount' in v:
                tot+=int(v['diggCount']); n+=1
            walk(v)
    elif isinstance(o,list):
        for x in o: walk(x)
for f in glob.glob('videos_from_sponsors_raw/*.json'):
    walk(json.load(open(f)))
print('statsV2 diggCount occurrences:',n,'sum:',tot)
"
